/** Reopen real generated bytes; inspect local recalculation/render copies without mutating versions. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {mkdtemp,mkdir,readFile,writeFile,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {runArtifactProcess} from '../../../../artifacts/process.mjs';
import {createLibreOfficeTransformer} from '../../../../artifacts/office-transform.mjs';

const hash = value => createHash('sha256').update(value).digest('hex');
export const workbookCell = (inspection,sheet,address) => inspection.sheets.find(value => value.name === sheet)?.cells.find(value => value.address === address);
export async function inspectWorkbook({bytes,pythonExecutable,directory,deadlineMs}) {
  const result = await runArtifactProcess(pythonExecutable,['-I','-B',fileURLToPath(new URL('./inspect_xlsx.py',import.meta.url))],
    {cwd: directory,input: bytes,deadlineMs});
  const inspection = JSON.parse(result.stdout);assert.equal(inspection.sha256,hash(bytes));
  return {inspection,process: result.receipt};
}
export async function inspectWorkbookCopies({bytes,label,expectedTotal,pythonExecutable,sofficeExecutable,tempRoot,outputDirectory,deadlineMs}) {
  assert.ok(['original','revision'].includes(label));
  const originalSha256 = hash(bytes),processes = [];
  await writeFile(join(outputDirectory,label+'.xlsx'),bytes,{flag: 'wx',mode: 0o600});
  const transformer = createLibreOfficeTransformer({executable: sofficeExecutable,tempRoot});
  const transformed = await transformer.transform({bytes,format: 'xlsx',target: 'xlsx',deadlineMs,maxBytes: 1048576});
  processes.push(transformed.receipt.process);
  const reopened = await inspectWorkbook({bytes: transformed.bytes,pythonExecutable,directory: tempRoot,deadlineMs});
  processes.push(reopened.process);
  assert.equal(workbookCell(reopened.inspection,'Plan','D4').value,'=SUM(D2:D3)');
  assert.equal(workbookCell(reopened.inspection,'Plan','D4').cached,expectedTotal);
  assert.equal(workbookCell(reopened.inspection,'Notes','A2').value,'=1+1');
  assert.equal(workbookCell(reopened.inspection,'Notes','A2').kind,'s');
  await writeFile(join(outputDirectory,label+'-recalculated.xlsx'),transformed.bytes,{flag: 'wx',mode: 0o600});
  const workspace = await mkdtemp(join(tempRoot,'workbook-render-'));
  try {
    await mkdir(join(workspace,'out'),{mode: 0o700});
    await writeFile(join(workspace,'input.xlsx'),transformed.bytes,{flag: 'wx',mode: 0o600});
    const run = await runArtifactProcess(sofficeExecutable,['-env:UserInstallation='+pathToFileURL(join(workspace,'profile')).href,
      '--headless','--nologo','--nodefault','--norestore','--convert-to','pdf:calc_pdf_Export','--outdir',join(workspace,'out'),join(workspace,'input.xlsx')],
      {cwd: workspace,input: Buffer.alloc(0),deadlineMs});
    processes.push(run.receipt);
    const pdf = await readFile(join(workspace,'out','input.pdf'));
    const rendered = await runArtifactProcess(pythonExecutable,['-I','-B',fileURLToPath(new URL('./inspect_pdf.py',import.meta.url))],
      {cwd: workspace,input: pdf,deadlineMs});
    processes.push(rendered.receipt);
    const visual = JSON.parse(rendered.stdout);assert.equal(visual.sha256,hash(pdf));
    const text = visual.pages.map(page => page.text).join('\n');
    assert.match(text,/Research/);assert.match(text,/Documentation/);assert.match(text,/Total/);
    assert.ok(text.includes(expectedTotal.toLocaleString('en-US',{minimumFractionDigits: 2})));
    await writeFile(join(outputDirectory,label+'-preview.pdf'),pdf,{flag: 'wx',mode: 0o600});
    for (const page of visual.pages) {
      assert.equal(page.png,`page-${page.page}.png`);
      const png = await readFile(join(workspace,page.png));assert.equal(hash(png),page.sha256);
      await writeFile(join(outputDirectory,`${label}-preview-${page.page}.png`),png,{flag: 'wx',mode: 0o600});
    }
    assert.equal(hash(bytes),originalSha256);
    return {sourceSha256: originalSha256,recalculation: {receipt: transformed.receipt,inspection: reopened.inspection},
      visual,processes,storedSourceUnchanged: true,localCopiesOnly: true,nativeQualified: false};
  } finally {await rm(workspace,{recursive: true,force: true});}
}
